<script setup lang="ts">
import type { Run, RunEvent, Artifact } from '../../../shared/types'
const id = String(useRoute().params.id)
const { data, error, refresh } = await useFetch<{ run: Run; metrics: RunEvent[]; logs: RunEvent[]; artifacts: Artifact[] }>(`/api/runs/${id}`, { server: false })
const { data: workspace } = await useWorkspace()
const busy = ref(false), actionError = ref(''), tab = ref('metrics')
const server = computed(() => workspace.value.servers.find(s => s.id === data.value?.run.serverId))
const latest = computed<Record<string, any>>(() => Object.assign({}, ...(data.value?.metrics.filter(m => m.kind === 'metric').map(m => m.payload) || [])))
const friendly: Record<string,string> = { eval_wer: 'Word error rate', eval_cer: 'Character error rate', eval_tamil_wer: 'Tamil WER', eval_latin_wer: 'Latin-token WER', eval_script_confusion: 'Script confusion' }
let timer: ReturnType<typeof setInterval>
onMounted(() => { timer = setInterval(() => { if (!document.hidden) refresh() }, 3000) })
onUnmounted(() => clearInterval(timer))
async function cancel() { busy.value = true; try { await $fetch(`/api/runs/${id}/cancel`, { method: 'POST' }); await refresh() } catch (e) { actionError.value = apiError(e) } finally { busy.value = false } }
const progress = computed(() => latest.value.total_steps ? Math.min(100, (latest.value.step || 0) / latest.value.total_steps * 100) : null)
</script>
<template><NuxtLink to="/runs" class="back-link"><AppIcon name="ArrowLeft" :size="16" />Experiments</NuxtLink><p v-if="error" class="alert error">{{ apiError(error) }}</p><template v-if="data"><div class="page-heading"><div><span class="eyebrow">EXPERIMENT / {{ id.slice(0, 8) }}</span><h1 class="run-title">{{ data.run.name }}</h1><p>{{ data.run.snapshot.model.name }}<span class="dot-divider">·</span>{{ data.run.snapshot.serverName }}<span class="dot-divider">·</span>{{ ago(data.run.createdAt) }}</p></div><div class="button-group"><NuxtLink :to="{ path: '/runs/new', query: { clone: id } }" class="button secondary"><AppIcon name="Copy" :size="16" />Duplicate</NuxtLink><button v-if="['running','queued'].includes(data.run.status)" class="button danger" :disabled="busy || data.run.cancelRequested" @click="cancel"><AppIcon name="Square" :size="14" />{{ data.run.cancelRequested ? 'Stopping…' : 'Stop run' }}</button></div></div><p v-if="actionError" class="alert error">{{ actionError }}</p><div v-if="data.run.status === 'running' && server && !isOnline(server)" class="alert warning"><AppIcon name="TriangleAlert" />Worker heartbeat is stale. State is unknown until it reconnects; no replacement job launches automatically.</div><div v-if="data.run.error" class="alert error"><AppIcon name="TriangleAlert" />{{ data.run.error }}</div><section class="panel run-status-bar"><StatusBadge :status="data.run.status" /><div class="run-progress"><div><span>{{ progress !== null ? `${progress.toFixed(1)}% complete` : data.run.status === 'queued' ? 'Waiting for worker' : 'Awaiting progress metrics' }}</span><span class="mono">{{ latest.step ?? '—' }} / {{ latest.total_steps ?? '—' }} steps</span></div><div class="meter"><span :style="{ width: `${progress || 0}%` }" /></div></div><div class="epoch-indicator"><small>EPOCH</small><strong>{{ typeof latest.epoch === 'number' ? latest.epoch.toFixed(2) : '—' }} <span>/ {{ data.run.config.epochs }}</span></strong></div></section><div class="toolbar"><div class="tabs"><button v-for="t in ['metrics','logs','configuration','artifacts']" :key="t" :class="{ selected: tab === t }" @click="tab = t">{{ t }}</button></div><span class="live-label"><span class="online-dot" />Refreshes every 3s</span></div><template v-if="tab === 'metrics'"><div class="chart-grid"><MetricChart :events="data.metrics" /><MetricChart :events="data.metrics" metric="eval_loss" title="Validation loss" /></div><section class="panel evaluation-panel"><div class="panel-heading"><div><h2>Evaluation</h2><p>Lower error rates are better. Compare on the same held-out data.</p></div><span class="pill">{{ data.run.snapshot.dataset.labelOrigin }} labels</span></div><div class="eval-grid"><div v-for="(label, metric) in friendly" :key="metric"><span>{{ label }}</span><strong>{{ typeof latest[metric] === 'number' ? `${(latest[metric] * 100).toFixed(2)}%` : '—' }}</strong></div></div><div v-if="data.run.snapshot.dataset.labelOrigin !== 'human'" class="evaluation-note">These metrics use {{ data.run.snapshot.dataset.labelOrigin }} reference labels, not fully human-verified ground truth.</div></section></template><section v-if="tab === 'logs'" class="panel log-panel"><div class="panel-heading"><h2><AppIcon name="Terminal" :size="17" />Worker output</h2><span class="subtle">Latest 300 entries</span></div><pre v-if="data.logs.length" class="log-content"><template v-for="log in data.logs" :key="log.id"><span class="log-time">{{ new Date(log.createdAt).toLocaleTimeString() }}</span> {{ log.payload.message }}{{ '\n' }}</template></pre><EmptyState v-else compact icon="Terminal" title="No output yet" description="Worker logs appear here when this run starts." /></section><section v-if="tab === 'configuration'" class="panel form-panel"><h2>Recorded configuration</h2><p class="subtle">A snapshot of the inputs used to create this experiment.</p><pre class="config-content">{{ JSON.stringify({ recipe: data.run.snapshot.recipe, model: data.run.snapshot.model.reference, dataset: data.run.snapshot.dataset.reference, ...data.run.config }, null, 2) }}</pre></section><section v-if="tab === 'artifacts'" class="panel"><div class="panel-heading"><div><h2>Checkpoints & outputs</h2><p>Files remain on the worker. Remote downloads are not enabled in this version.</p></div></div><div v-if="data.artifacts.length" class="artifact-list"><div v-for="artifact in data.artifacts" :key="artifact.id"><span class="resource-icon"><AppIcon name="FolderOpen" /></span><div><strong>{{ artifact.name }}</strong><p class="mono">{{ artifact.path }}</p></div><span class="pill">{{ artifact.kind }}</span></div></div><EmptyState v-else compact icon="FolderOpen" title="No saved outputs yet" description="Exported adapters and available checkpoints are recorded when training finishes." /></section></template><div v-else-if="!error" class="loading-state"><AppIcon name="LoaderCircle" />Loading experiment…</div></template>
